alternatives.fix_snippet:
display: inline-flex;
align-items: center;
justify-content: center;
padding: 7px 7px;

position: relative;
&::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  min-width: 24px;
  min-height: 24px;
  width: 100%;
  height: 100%;
}
